MTPerror::MTPerror() : type_owner(new MTPDerror()) {
}
mtpTypeId MTPerror::type() const {
	return mtpc_error;
}
bool MTPerror::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	if (cons != mtpc_error) return false;
	if (const auto data = new MTPDerror(); data->read(from, end)) {
		setData(data);
	} else {
		delete data;
		return false;
	}
	return true;
}
template <typename Accumulator>
void MTPerror::write(Accumulator &to) const {
	const MTPDerror &v = c_error();
	v.vcode().write(to);
	v.vtext().write(to);
}
