MTPinputPeer::MTPinputPeer() = default;
mtpTypeId MTPinputPeer::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPinputPeer::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_inputPeerEmpty: _type = cons; break;
	case mtpc_inputPeerSelf: _type = cons; break;
	case mtpc_inputPeerChat: _type = cons; {
		if (const auto data = new MTPDinputPeerChat(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputPeerUser: _type = cons; {
		if (const auto data = new MTPDinputPeerUser(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputPeerChannel: _type = cons; {
		if (const auto data = new MTPDinputPeerChannel(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputPeerUserFromMessage: _type = cons; {
		if (const auto data = new MTPDinputPeerUserFromMessage(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputPeerChannelFromMessage: _type = cons; {
		if (const auto data = new MTPDinputPeerChannelFromMessage(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPinputPeer::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_inputPeerChat: {
		const MTPDinputPeerChat &v = c_inputPeerChat();
		v.vchat_id().write(to);
	} break;
	case mtpc_inputPeerUser: {
		const MTPDinputPeerUser &v = c_inputPeerUser();
		v.vuser_id().write(to);
		v.vaccess_hash().write(to);
	} break;
	case mtpc_inputPeerChannel: {
		const MTPDinputPeerChannel &v = c_inputPeerChannel();
		v.vchannel_id().write(to);
		v.vaccess_hash().write(to);
	} break;
	case mtpc_inputPeerUserFromMessage: {
		const MTPDinputPeerUserFromMessage &v = c_inputPeerUserFromMessage();
		v.vpeer().write(to);
		v.vmsg_id().write(to);
		v.vuser_id().write(to);
	} break;
	case mtpc_inputPeerChannelFromMessage: {
		const MTPDinputPeerChannelFromMessage &v = c_inputPeerChannelFromMessage();
		v.vpeer().write(to);
		v.vmsg_id().write(to);
		v.vchannel_id().write(to);
	} break;
	}
}
