bool MTPinputChatPhoto::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_inputChatPhotoEmpty: _type = cons; break;
	case mtpc_inputChatUploadedPhoto: _type = cons; {
		if (const auto data = new MTPDinputChatUploadedPhoto(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputChatPhoto: _type = cons; {
		if (const auto data = new MTPDinputChatPhoto(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPinputChatPhoto::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_inputChatUploadedPhoto: {
		const MTPDinputChatUploadedPhoto &v = c_inputChatUploadedPhoto();
		v.vflags().write(to);
		if (const auto vfile = v.vfile()) vfile->write(to);
		if (const auto vvideo = v.vvideo()) vvideo->write(to);
		if (const auto vvideo_start_ts = v.vvideo_start_ts()) vvideo_start_ts->write(to);
		if (const auto vvideo_emoji_markup = v.vvideo_emoji_markup()) vvideo_emoji_markup->write(to);
	} break;
	case mtpc_inputChatPhoto: {
		const MTPDinputChatPhoto &v = c_inputChatPhoto();
		v.vid().write(to);
	} break;
	}
}
