template <typename Accumulator>
void MTPinputFileLocation::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_inputFileLocation: {
		const MTPDinputFileLocation &v = c_inputFileLocation();
		v.vvolume_id().write(to);
		v.vlocal_id().write(to);
		v.vsecret().write(to);
		v.vfile_reference().write(to);
	} break;
	case mtpc_inputEncryptedFileLocation: {
		const MTPDinputEncryptedFileLocation &v = c_inputEncryptedFileLocation();
		v.vid().write(to);
		v.vaccess_hash().write(to);
	} break;
	case mtpc_inputDocumentFileLocation: {
		const MTPDinputDocumentFileLocation &v = c_inputDocumentFileLocation();
		v.vid().write(to);
		v.vaccess_hash().write(to);
		v.vfile_reference().write(to);
		v.vthumb_size().write(to);
	} break;
	case mtpc_inputSecureFileLocation: {
		const MTPDinputSecureFileLocation &v = c_inputSecureFileLocation();
		v.vid().write(to);
		v.vaccess_hash().write(to);
	} break;
	case mtpc_inputPhotoFileLocation: {
		const MTPDinputPhotoFileLocation &v = c_inputPhotoFileLocation();
		v.vid().write(to);
		v.vaccess_hash().write(to);
		v.vfile_reference().write(to);
		v.vthumb_size().write(to);
	} break;
	case mtpc_inputPhotoLegacyFileLocation: {
		const MTPDinputPhotoLegacyFileLocation &v = c_inputPhotoLegacyFileLocation();
		v.vid().write(to);
		v.vaccess_hash().write(to);
		v.vfile_reference().write(to);
		v.vvolume_id().write(to);
		v.vlocal_id().write(to);
		v.vsecret().write(to);
	} break;
	case mtpc_inputPeerPhotoFileLocation: {
		const MTPDinputPeerPhotoFileLocation &v = c_inputPeerPhotoFileLocation();
		v.vflags().write(to);
		v.vpeer().write(to);
		v.vphoto_id().write(to);
	} break;
	case mtpc_inputStickerSetThumb: {
		const MTPDinputStickerSetThumb &v = c_inputStickerSetThumb();
		v.vstickerset().write(to);
		v.vthumb_version().write(to);
	} break;
	case mtpc_inputGroupCallStream: {
		const MTPDinputGroupCallStream &v = c_inputGroupCallStream();
		v.vflags().write(to);
		v.vcall().write(to);
		v.vtime_ms().write(to);
		v.vscale().write(to);
		if (const auto vvideo_channel = v.vvideo_channel()) vvideo_channel->write(to);
		if (const auto vvideo_quality = v.vvideo_quality()) vvideo_quality->write(to);
	} break;
	}
}
