bool MTPuser::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_userEmpty: _type = cons; {
		if (const auto data = new MTPDuserEmpty(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_user: _type = cons; {
		if (const auto data = new MTPDuser(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPuser::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_userEmpty: {
		const MTPDuserEmpty &v = c_userEmpty();
		v.vid().write(to);
	} break;
	case mtpc_user: {
		const MTPDuser &v = c_user();
		v.vflags().write(to);
		v.vid().write(to);
		if (const auto vaccess_hash = v.vaccess_hash()) vaccess_hash->write(to);
		if (const auto vfirst_name = v.vfirst_name()) vfirst_name->write(to);
		if (const auto vlast_name = v.vlast_name()) vlast_name->write(to);
		if (const auto vusername = v.vusername()) vusername->write(to);
		if (const auto vphone = v.vphone()) vphone->write(to);
		if (const auto vphoto = v.vphoto()) vphoto->write(to);
		if (const auto vstatus = v.vstatus()) vstatus->write(to);
		if (const auto vbot_info_version = v.vbot_info_version()) vbot_info_version->write(to);
		if (const auto vrestriction_reason = v.vrestriction_reason()) vrestriction_reason->write(to);
		if (const auto vbot_inline_placeholder = v.vbot_inline_placeholder()) vbot_inline_placeholder->write(to);
		if (const auto vlang_code = v.vlang_code()) vlang_code->write(to);
		if (const auto vemoji_status = v.vemoji_status()) vemoji_status->write(to);
		if (const auto vusernames = v.vusernames()) vusernames->write(to);
		if (const auto vstories_max_id = v.vstories_max_id()) vstories_max_id->write(to);
		if (const auto vcolor = v.vcolor()) vcolor->write(to);
		if (const auto vprofile_color = v.vprofile_color()) vprofile_color->write(to);
		if (const auto vbot_active_users = v.vbot_active_users()) vbot_active_users->write(to);
		if (const auto vbot_verification_icon = v.vbot_verification_icon()) vbot_verification_icon->write(to);
		if (const auto vsend_paid_messages_stars = v.vsend_paid_messages_stars()) vsend_paid_messages_stars->write(to);
	} break;
	}
}
