bool MTPDuser::read(const mtpPrime *&from, const mtpPrime *end) {
	return _flags.read(from, end)
		&& _id.read(from, end)
		&& (vaccess_hash() ? _access_hash.read(from, end) : ((_access_hash = MTPlong()), true))
		&& (vfirst_name() ? _first_name.read(from, end) : ((_first_name = MTPstring()), true))
		&& (vlast_name() ? _last_name.read(from, end) : ((_last_name = MTPstring()), true))
		&& (vusername() ? _username.read(from, end) : ((_username = MTPstring()), true))
		&& (vphone() ? _phone.read(from, end) : ((_phone = MTPstring()), true))
		&& (vphoto() ? _photo.read(from, end) : ((_photo = MTPUserProfilePhoto()), true))
		&& (vstatus() ? _status.read(from, end) : ((_status = MTPUserStatus()), true))
		&& (vbot_info_version() ? _bot_info_version.read(from, end) : ((_bot_info_version = MTPint()), true))
		&& (vrestriction_reason() ? _restriction_reason.read(from, end) : ((_restriction_reason = MTPVector<MTPRestrictionReason>()), true))
		&& (vbot_inline_placeholder() ? _bot_inline_placeholder.read(from, end) : ((_bot_inline_placeholder = MTPstring()), true))
		&& (vlang_code() ? _lang_code.read(from, end) : ((_lang_code = MTPstring()), true))
		&& (vemoji_status() ? _emoji_status.read(from, end) : ((_emoji_status = MTPEmojiStatus()), true))
		&& (vusernames() ? _usernames.read(from, end) : ((_usernames = MTPVector<MTPUsername>()), true))
		&& (vstories_max_id() ? _stories_max_id.read(from, end) : ((_stories_max_id = MTPint()), true))
		&& (vcolor() ? _color.read(from, end) : ((_color = MTPPeerColor()), true))
		&& (vprofile_color() ? _profile_color.read(from, end) : ((_profile_color = MTPPeerColor()), true))
		&& (vbot_active_users() ? _bot_active_users.read(from, end) : ((_bot_active_users = MTPint()), true))
		&& (vbot_verification_icon() ? _bot_verification_icon.read(from, end) : ((_bot_verification_icon = MTPlong()), true))
		&& (vsend_paid_messages_stars() ? _send_paid_messages_stars.read(from, end) : ((_send_paid_messages_stars = MTPlong()), true));
}
