bool MTPchat::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_chatEmpty: _type = cons; {
		if (const auto data = new MTPDchatEmpty(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_chat: _type = cons; {
		if (const auto data = new MTPDchat(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_chatForbidden: _type = cons; {
		if (const auto data = new MTPDchatForbidden(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_channel: _type = cons; {
		if (const auto data = new MTPDchannel(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_channelForbidden: _type = cons; {
		if (const auto data = new MTPDchannelForbidden(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPchat::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_chatEmpty: {
		const MTPDchatEmpty &v = c_chatEmpty();
		v.vid().write(to);
	} break;
	case mtpc_chat: {
		const MTPDchat &v = c_chat();
		v.vflags().write(to);
		v.vid().write(to);
		v.vtitle().write(to);
		v.vphoto().write(to);
		v.vparticipants_count().write(to);
		v.vdate().write(to);
		v.vversion().write(to);
		if (const auto vmigrated_to = v.vmigrated_to()) vmigrated_to->write(to);
		if (const auto vadmin_rights = v.vadmin_rights()) vadmin_rights->write(to);
		if (const auto vdefault_banned_rights = v.vdefault_banned_rights()) vdefault_banned_rights->write(to);
	} break;
	case mtpc_chatForbidden: {
		const MTPDchatForbidden &v = c_chatForbidden();
		v.vid().write(to);
		v.vtitle().write(to);
	} break;
	case mtpc_channel: {
		const MTPDchannel &v = c_channel();
		v.vflags().write(to);
		v.vid().write(to);
		if (const auto vaccess_hash = v.vaccess_hash()) vaccess_hash->write(to);
		v.vtitle().write(to);
		if (const auto vusername = v.vusername()) vusername->write(to);
		v.vphoto().write(to);
		v.vdate().write(to);
		if (const auto vrestriction_reason = v.vrestriction_reason()) vrestriction_reason->write(to);
		if (const auto vadmin_rights = v.vadmin_rights()) vadmin_rights->write(to);
		if (const auto vbanned_rights = v.vbanned_rights()) vbanned_rights->write(to);
		if (const auto vdefault_banned_rights = v.vdefault_banned_rights()) vdefault_banned_rights->write(to);
		if (const auto vparticipants_count = v.vparticipants_count()) vparticipants_count->write(to);
		if (const auto vusernames = v.vusernames()) vusernames->write(to);
		if (const auto vstories_max_id = v.vstories_max_id()) vstories_max_id->write(to);
		if (const auto vcolor = v.vcolor()) vcolor->write(to);
		if (const auto vprofile_color = v.vprofile_color()) vprofile_color->write(to);
		if (const auto vemoji_status = v.vemoji_status()) vemoji_status->write(to);
		if (const auto vlevel = v.vlevel()) vlevel->write(to);
		if (const auto vsubscription_until_date = v.vsubscription_until_date()) vsubscription_until_date->write(to);
		if (const auto vbot_verification_icon = v.vbot_verification_icon()) vbot_verification_icon->write(to);
		if (const auto vsend_paid_messages_stars = v.vsend_paid_messages_stars()) vsend_paid_messages_stars->write(to);
		if (const auto vlinked_monoforum_id = v.vlinked_monoforum_id()) vlinked_monoforum_id->write(to);
	} break;
	case mtpc_channelForbidden: {
		const MTPDchannelForbidden &v = c_channelForbidden();
		v.vflags().write(to);
		v.vid().write(to);
		v.vaccess_hash().write(to);
		v.vtitle().write(to);
		if (const auto vuntil_date = v.vuntil_date()) vuntil_date->write(to);
	} break;
	}
}
