mtpTypeId MTPchatFull::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPchatFull::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_chatFull: _type = cons; {
		if (const auto data = new MTPDchatFull(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_channelFull: _type = cons; {
		if (const auto data = new MTPDchannelFull(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPchatFull::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_chatFull: {
		const MTPDchatFull &v = c_chatFull();
		v.vflags().write(to);
		v.vid().write(to);
		v.vabout().write(to);
		v.vparticipants().write(to);
		if (const auto vchat_photo = v.vchat_photo()) vchat_photo->write(to);
		v.vnotify_settings().write(to);
		if (const auto vexported_invite = v.vexported_invite()) vexported_invite->write(to);
		if (const auto vbot_info = v.vbot_info()) vbot_info->write(to);
		if (const auto vpinned_msg_id = v.vpinned_msg_id()) vpinned_msg_id->write(to);
		if (const auto vfolder_id = v.vfolder_id()) vfolder_id->write(to);
		if (const auto vcall = v.vcall()) vcall->write(to);
		if (const auto vttl_period = v.vttl_period()) vttl_period->write(to);
		if (const auto vgroupcall_default_join_as = v.vgroupcall_default_join_as()) vgroupcall_default_join_as->write(to);
		if (const auto vtheme_emoticon = v.vtheme_emoticon()) vtheme_emoticon->write(to);
		if (const auto vrequests_pending = v.vrequests_pending()) vrequests_pending->write(to);
		if (const auto vrecent_requesters = v.vrecent_requesters()) vrecent_requesters->write(to);
		if (const auto vavailable_reactions = v.vavailable_reactions()) vavailable_reactions->write(to);
		if (const auto vreactions_limit = v.vreactions_limit()) vreactions_limit->write(to);
	} break;
	case mtpc_channelFull: {
		const MTPDchannelFull &v = c_channelFull();
		v.vflags().write(to);
		v.vid().write(to);
		v.vabout().write(to);
		if (const auto vparticipants_count = v.vparticipants_count()) vparticipants_count->write(to);
		if (const auto vadmins_count = v.vadmins_count()) vadmins_count->write(to);
		if (const auto vkicked_count = v.vkicked_count()) vkicked_count->write(to);
		if (const auto vbanned_count = v.vbanned_count()) vbanned_count->write(to);
		if (const auto vonline_count = v.vonline_count()) vonline_count->write(to);
		v.vread_inbox_max_id().write(to);
		v.vread_outbox_max_id().write(to);
		v.vunread_count().write(to);
		v.vchat_photo().write(to);
		v.vnotify_settings().write(to);
		if (const auto vexported_invite = v.vexported_invite()) vexported_invite->write(to);
		v.vbot_info().write(to);
		if (const auto vmigrated_from_chat_id = v.vmigrated_from_chat_id()) vmigrated_from_chat_id->write(to);
		if (const auto vmigrated_from_max_id = v.vmigrated_from_max_id()) vmigrated_from_max_id->write(to);
		if (const auto vpinned_msg_id = v.vpinned_msg_id()) vpinned_msg_id->write(to);
		if (const auto vstickerset = v.vstickerset()) vstickerset->write(to);
		if (const auto vavailable_min_id = v.vavailable_min_id()) vavailable_min_id->write(to);
		if (const auto vfolder_id = v.vfolder_id()) vfolder_id->write(to);
		if (const auto vlinked_chat_id = v.vlinked_chat_id()) vlinked_chat_id->write(to);
		if (const auto vlocation = v.vlocation()) vlocation->write(to);
		if (const auto vslowmode_seconds = v.vslowmode_seconds()) vslowmode_seconds->write(to);
		if (const auto vslowmode_next_send_date = v.vslowmode_next_send_date()) vslowmode_next_send_date->write(to);
		if (const auto vstats_dc = v.vstats_dc()) vstats_dc->write(to);
		v.vpts().write(to);
		if (const auto vcall = v.vcall()) vcall->write(to);
		if (const auto vttl_period = v.vttl_period()) vttl_period->write(to);
		if (const auto vpending_suggestions = v.vpending_suggestions()) vpending_suggestions->write(to);
		if (const auto vgroupcall_default_join_as = v.vgroupcall_default_join_as()) vgroupcall_default_join_as->write(to);
		if (const auto vtheme_emoticon = v.vtheme_emoticon()) vtheme_emoticon->write(to);
		if (const auto vrequests_pending = v.vrequests_pending()) vrequests_pending->write(to);
		if (const auto vrecent_requesters = v.vrecent_requesters()) vrecent_requesters->write(to);
		if (const auto vdefault_send_as = v.vdefault_send_as()) vdefault_send_as->write(to);
		if (const auto vavailable_reactions = v.vavailable_reactions()) vavailable_reactions->write(to);
		if (const auto vreactions_limit = v.vreactions_limit()) vreactions_limit->write(to);
		if (const auto vstories = v.vstories()) vstories->write(to);
		if (const auto vwallpaper = v.vwallpaper()) vwallpaper->write(to);
		if (const auto vboosts_applied = v.vboosts_applied()) vboosts_applied->write(to);
		if (const auto vboosts_unrestrict = v.vboosts_unrestrict()) vboosts_unrestrict->write(to);
		if (const auto vemojiset = v.vemojiset()) vemojiset->write(to);
		if (const auto vbot_verification = v.vbot_verification()) vbot_verification->write(to);
		if (const auto vstargifts_count = v.vstargifts_count()) vstargifts_count->write(to);
		if (const auto vsend_paid_messages_stars = v.vsend_paid_messages_stars()) vsend_paid_messages_stars->write(to);
		if (const auto vmain_tab = v.vmain_tab()) vmain_tab->write(to);
	} break;
	}
}
