bool MTPDmessageService::read(const mtpPrime *&from, const mtpPrime *end) {
	return _flags.read(from, end)
		&& _id.read(from, end)
		&& (vfrom_id() ? _from_id.read(from, end) : ((_from_id = MTPPeer()), true))
		&& _peer_id.read(from, end)
		&& (vsaved_peer_id() ? _saved_peer_id.read(from, end) : ((_saved_peer_id = MTPPeer()), true))
		&& (vreply_to() ? _reply_to.read(from, end) : ((_reply_to = MTPMessageReplyHeader()), true))
		&& _date.read(from, end)
		&& _action.read(from, end)
		&& (vreactions() ? _reactions.read(from, end) : ((_reactions = MTPMessageReactions()), true))
		&& (vttl_period() ? _ttl_period.read(from, end) : ((_ttl_period = MTPint()), true));
}
