template <typename Accumulator>
void MTPmessageMedia::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_messageMediaPhoto: {
		const MTPDmessageMediaPhoto &v = c_messageMediaPhoto();
		v.vflags().write(to);
		if (const auto vphoto = v.vphoto()) vphoto->write(to);
		if (const auto vttl_seconds = v.vttl_seconds()) vttl_seconds->write(to);
	} break;
	case mtpc_messageMediaGeo: {
		const MTPDmessageMediaGeo &v = c_messageMediaGeo();
		v.vgeo().write(to);
	} break;
	case mtpc_messageMediaContact: {
		const MTPDmessageMediaContact &v = c_messageMediaContact();
		v.vphone_number().write(to);
		v.vfirst_name().write(to);
		v.vlast_name().write(to);
		v.vvcard().write(to);
		v.vuser_id().write(to);
	} break;
	case mtpc_messageMediaDocument: {
		const MTPDmessageMediaDocument &v = c_messageMediaDocument();
		v.vflags().write(to);
		if (const auto vdocument = v.vdocument()) vdocument->write(to);
		if (const auto valt_documents = v.valt_documents()) valt_documents->write(to);
		if (const auto vvideo_cover = v.vvideo_cover()) vvideo_cover->write(to);
		if (const auto vvideo_timestamp = v.vvideo_timestamp()) vvideo_timestamp->write(to);
		if (const auto vttl_seconds = v.vttl_seconds()) vttl_seconds->write(to);
	} break;
	case mtpc_messageMediaWebPage: {
		const MTPDmessageMediaWebPage &v = c_messageMediaWebPage();
		v.vflags().write(to);
		v.vwebpage().write(to);
	} break;
	case mtpc_messageMediaVenue: {
		const MTPDmessageMediaVenue &v = c_messageMediaVenue();
		v.vgeo().write(to);
		v.vtitle().write(to);
		v.vaddress().write(to);
		v.vprovider().write(to);
		v.vvenue_id().write(to);
		v.vvenue_type().write(to);
	} break;
	case mtpc_messageMediaGame: {
		const MTPDmessageMediaGame &v = c_messageMediaGame();
		v.vgame().write(to);
	} break;
	case mtpc_messageMediaInvoice: {
		const MTPDmessageMediaInvoice &v = c_messageMediaInvoice();
		v.vflags().write(to);
		v.vtitle().write(to);
		v.vdescription().write(to);
		if (const auto vphoto = v.vphoto()) vphoto->write(to);
		if (const auto vreceipt_msg_id = v.vreceipt_msg_id()) vreceipt_msg_id->write(to);
		v.vcurrency().write(to);
		v.vtotal_amount().write(to);
		v.vstart_param().write(to);
		if (const auto vextended_media = v.vextended_media()) vextended_media->write(to);
	} break;
	case mtpc_messageMediaGeoLive: {
		const MTPDmessageMediaGeoLive &v = c_messageMediaGeoLive();
		v.vflags().write(to);
		v.vgeo().write(to);
		if (const auto vheading = v.vheading()) vheading->write(to);
		v.vperiod().write(to);
		if (const auto vproximity_notification_radius = v.vproximity_notification_radius()) vproximity_notification_radius->write(to);
	} break;
	case mtpc_messageMediaPoll: {
		const MTPDmessageMediaPoll &v = c_messageMediaPoll();
		v.vpoll().write(to);
		v.vresults().write(to);
	} break;
	case mtpc_messageMediaDice: {
		const MTPDmessageMediaDice &v = c_messageMediaDice();
		v.vvalue().write(to);
		v.vemoticon().write(to);
	} break;
	case mtpc_messageMediaStory: {
		const MTPDmessageMediaStory &v = c_messageMediaStory();
		v.vflags().write(to);
		v.vpeer().write(to);
		v.vid().write(to);
		if (const auto vstory = v.vstory()) vstory->write(to);
	} break;
	case mtpc_messageMediaGiveaway: {
		const MTPDmessageMediaGiveaway &v = c_messageMediaGiveaway();
		v.vflags().write(to);
		v.vchannels().write(to);
		if (const auto vcountries_iso2 = v.vcountries_iso2()) vcountries_iso2->write(to);
		if (const auto vprize_description = v.vprize_description()) vprize_description->write(to);
		v.vquantity().write(to);
		if (const auto vmonths = v.vmonths()) vmonths->write(to);
		if (const auto vstars = v.vstars()) vstars->write(to);
		v.vuntil_date().write(to);
	} break;
	case mtpc_messageMediaGiveawayResults: {
		const MTPDmessageMediaGiveawayResults &v = c_messageMediaGiveawayResults();
		v.vflags().write(to);
		v.vchannel_id().write(to);
		if (const auto vadditional_peers_count = v.vadditional_peers_count()) vadditional_peers_count->write(to);
		v.vlaunch_msg_id().write(to);
		v.vwinners_count().write(to);
		v.vunclaimed_count().write(to);
		v.vwinners().write(to);
		if (const auto vmonths = v.vmonths()) vmonths->write(to);
		if (const auto vstars = v.vstars()) vstars->write(to);
		if (const auto vprize_description = v.vprize_description()) vprize_description->write(to);
		v.vuntil_date().write(to);
	} break;
	case mtpc_messageMediaPaidMedia: {
		const MTPDmessageMediaPaidMedia &v = c_messageMediaPaidMedia();
		v.vstars_amount().write(to);
		v.vextended_media().write(to);
	} break;
	case mtpc_messageMediaToDo: {
		const MTPDmessageMediaToDo &v = c_messageMediaToDo();
		v.vflags().write(to);
		v.vtodo().write(to);
		if (const auto vcompletions = v.vcompletions()) vcompletions->write(to);
	} break;
	}
}
