bool MTPdialog::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_dialog: _type = cons; {
		if (const auto data = new MTPDdialog(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_dialogFolder: _type = cons; {
		if (const auto data = new MTPDdialogFolder(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPdialog::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_dialog: {
		const MTPDdialog &v = c_dialog();
		v.vflags().write(to);
		v.vpeer().write(to);
		v.vtop_message().write(to);
		v.vread_inbox_max_id().write(to);
		v.vread_outbox_max_id().write(to);
		v.vunread_count().write(to);
		v.vunread_mentions_count().write(to);
		v.vunread_reactions_count().write(to);
		v.vnotify_settings().write(to);
		if (const auto vpts = v.vpts()) vpts->write(to);
		if (const auto vdraft = v.vdraft()) vdraft->write(to);
		if (const auto vfolder_id = v.vfolder_id()) vfolder_id->write(to);
		if (const auto vttl_period = v.vttl_period()) vttl_period->write(to);
	} break;
	case mtpc_dialogFolder: {
		const MTPDdialogFolder &v = c_dialogFolder();
		v.vflags().write(to);
		v.vfolder().write(to);
		v.vpeer().write(to);
		v.vtop_message().write(to);
		v.vunread_muted_peers_count().write(to);
		v.vunread_unmuted_peers_count().write(to);
		v.vunread_muted_messages_count().write(to);
		v.vunread_unmuted_messages_count().write(to);
	} break;
	}
}
