bool MTPwallPaper::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_wallPaper: _type = cons; {
		if (const auto data = new MTPDwallPaper(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_wallPaperNoFile: _type = cons; {
		if (const auto data = new MTPDwallPaperNoFile(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPwallPaper::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_wallPaper: {
		const MTPDwallPaper &v = c_wallPaper();
		v.vid().write(to);
		v.vflags().write(to);
		v.vaccess_hash().write(to);
		v.vslug().write(to);
		v.vdocument().write(to);
		if (const auto vsettings = v.vsettings()) vsettings->write(to);
	} break;
	case mtpc_wallPaperNoFile: {
		const MTPDwallPaperNoFile &v = c_wallPaperNoFile();
		v.vid().write(to);
		v.vflags().write(to);
		if (const auto vsettings = v.vsettings()) vsettings->write(to);
	} break;
	}
}
