MTPDupdateNewMessage::MTPDupdateNewMessage() = default;
const MTPDupdateNewMessage &MTPupdate::c_updateNewMessage() const {
	Expects(_type == mtpc_updateNewMessage);

	return queryData<MTPDupdateNewMessage>();
}
MTPupdate::MTPupdate(const MTPDupdateNewMessage *data) : type_owner(data), _type(mtpc_updateNewMessage) {
}
MTPDupdateNewMessage::MTPDupdateNewMessage(const MTPMessage &message_, MTPint pts_, MTPint pts_count_) : _message(message_), _pts(pts_), _pts_count(pts_count_) {
}
bool MTPDupdateNewMessage::read(const mtpPrime *&from, const mtpPrime *end) {
	return _message.read(from, end)
		&& _pts.read(from, end)
		&& _pts_count.read(from, end);
}
const MTPMessage &MTPDupdateNewMessage::vmessage() const {
	return _message;
}
const MTPint &MTPDupdateNewMessage::vpts() const {
	return _pts;
}
const MTPint &MTPDupdateNewMessage::vpts_count() const {
	return _pts_count;
}
MTPDupdateMessageID::MTPDupdateMessageID() = default;
const MTPDupdateMessageID &MTPupdate::c_updateMessageID() const {
	Expects(_type == mtpc_updateMessageID);

	return queryData<MTPDupdateMessageID>();
}
MTPupdate::MTPupdate(const MTPDupdateMessageID *data) : type_owner(data), _type(mtpc_updateMessageID) {
}
MTPDupdateMessageID::MTPDupdateMessageID(MTPint id_, MTPlong random_id_) : _id(id_), _random_id(random_id_) {
}
bool MTPDupdateMessageID::read(const mtpPrime *&from, const mtpPrime *end) {
	return _id.read(from, end)
		&& _random_id.read(from, end);
}
const MTPint &MTPDupdateMessageID::vid() const {
	return _id;
}
const MTPlong &MTPDupdateMessageID::vrandom_id() const {
	return _random_id;
}
