mtpTypeId MTPupdates::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPupdates::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_updatesTooLong: _type = cons; break;
	case mtpc_updateShortMessage: _type = cons; {
		if (const auto data = new MTPDupdateShortMessage(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_updateShortChatMessage: _type = cons; {
		if (const auto data = new MTPDupdateShortChatMessage(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_updateShort: _type = cons; {
		if (const auto data = new MTPDupdateShort(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_updatesCombined: _type = cons; {
		if (const auto data = new MTPDupdatesCombined(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_updates: _type = cons; {
		if (const auto data = new MTPDupdates(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_updateShortSentMessage: _type = cons; {
		if (const auto data = new MTPDupdateShortSentMessage(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPupdates::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_updateShortMessage: {
		const MTPDupdateShortMessage &v = c_updateShortMessage();
		v.vflags().write(to);
		v.vid().write(to);
		v.vuser_id().write(to);
		v.vmessage().write(to);
		v.vpts().write(to);
		v.vpts_count().write(to);
		v.vdate().write(to);
		if (const auto vfwd_from = v.vfwd_from()) vfwd_from->write(to);
		if (const auto vvia_bot_id = v.vvia_bot_id()) vvia_bot_id->write(to);
		if (const auto vreply_to = v.vreply_to()) vreply_to->write(to);
		if (const auto ventities = v.ventities()) ventities->write(to);
		if (const auto vttl_period = v.vttl_period()) vttl_period->write(to);
	} break;
	case mtpc_updateShortChatMessage: {
		const MTPDupdateShortChatMessage &v = c_updateShortChatMessage();
		v.vflags().write(to);
		v.vid().write(to);
		v.vfrom_id().write(to);
		v.vchat_id().write(to);
		v.vmessage().write(to);
		v.vpts().write(to);
		v.vpts_count().write(to);
		v.vdate().write(to);
		if (const auto vfwd_from = v.vfwd_from()) vfwd_from->write(to);
		if (const auto vvia_bot_id = v.vvia_bot_id()) vvia_bot_id->write(to);
		if (const auto vreply_to = v.vreply_to()) vreply_to->write(to);
		if (const auto ventities = v.ventities()) ventities->write(to);
		if (const auto vttl_period = v.vttl_period()) vttl_period->write(to);
	} break;
	case mtpc_updateShort: {
		const MTPDupdateShort &v = c_updateShort();
		v.vupdate().write(to);
		v.vdate().write(to);
	} break;
	case mtpc_updatesCombined: {
		const MTPDupdatesCombined &v = c_updatesCombined();
		v.vupdates().write(to);
		v.vusers().write(to);
		v.vchats().write(to);
		v.vdate().write(to);
		v.vseq_start().write(to);
		v.vseq().write(to);
	} break;
	case mtpc_updates: {
		const MTPDupdates &v = c_updates();
		v.vupdates().write(to);
		v.vusers().write(to);
		v.vchats().write(to);
		v.vdate().write(to);
		v.vseq().write(to);
	} break;
	case mtpc_updateShortSentMessage: {
		const MTPDupdateShortSentMessage &v = c_updateShortSentMessage();
		v.vflags().write(to);
		v.vid().write(to);
		v.vpts().write(to);
		v.vpts_count().write(to);
		v.vdate().write(to);
		if (const auto vmedia = v.vmedia()) vmedia->write(to);
		if (const auto ventities = v.ventities()) ventities->write(to);
		if (const auto vttl_period = v.vttl_period()) vttl_period->write(to);
	} break;
	}
}
template void MTPupdates::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPupdates::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPupdates::MTPupdates(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_updatesTooLong: break;
	case mtpc_updateShortMessage: setData(new MTPDupdateShortMessage()); break;
	case mtpc_updateShortChatMessage: setData(new MTPDupdateShortChatMessage()); break;
	case mtpc_updateShort: setData(new MTPDupdateShort()); break;
	case mtpc_updatesCombined: setData(new MTPDupdatesCombined()); break;
	case mtpc_updates: setData(new MTPDupdates()); break;
	case mtpc_updateShortSentMessage: setData(new MTPDupdateShortSentMessage()); break;
	default: Unexpected("Type in MTPupdates::MTPupdates.");
	}
}
