MTPdocument MTP_document(const MTPflags<MTPDdocument::Flags> &flags_, MTPlong id_, MTPlong access_hash_, const MTPbytes &file_reference_, MTPint date_, const MTPstring &mime_type_, MTPlong size_, const MTPVector<MTPPhotoSize> &thumbs_, const MTPVector<MTPVideoSize> &video_thumbs_, MTPint dc_id_, const MTPVector<MTPDocumentAttribute> &attributes_) {
	return ::MTP::details::TypeCreator::new_document(flags_, id_, access_hash_, file_reference_, date_, mime_type_, size_, thumbs_, video_thumbs_, dc_id_, attributes_);
}

