bool MTPdocumentAttribute::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_documentAttributeImageSize: _type = cons; {
		if (const auto data = new MTPDdocumentAttributeImageSize(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_documentAttributeAnimated: _type = cons; break;
	case mtpc_documentAttributeSticker: _type = cons; {
		if (const auto data = new MTPDdocumentAttributeSticker(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_documentAttributeVideo: _type = cons; {
		if (const auto data = new MTPDdocumentAttributeVideo(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_documentAttributeAudio: _type = cons; {
		if (const auto data = new MTPDdocumentAttributeAudio(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_documentAttributeFilename: _type = cons; {
		if (const auto data = new MTPDdocumentAttributeFilename(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_documentAttributeHasStickers: _type = cons; break;
	case mtpc_documentAttributeCustomEmoji: _type = cons; {
		if (const auto data = new MTPDdocumentAttributeCustomEmoji(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPdocumentAttribute::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_documentAttributeImageSize: {
		const MTPDdocumentAttributeImageSize &v = c_documentAttributeImageSize();
		v.vw().write(to);
		v.vh().write(to);
	} break;
	case mtpc_documentAttributeSticker: {
		const MTPDdocumentAttributeSticker &v = c_documentAttributeSticker();
		v.vflags().write(to);
		v.valt().write(to);
		v.vstickerset().write(to);
		if (const auto vmask_coords = v.vmask_coords()) vmask_coords->write(to);
	} break;
	case mtpc_documentAttributeVideo: {
		const MTPDdocumentAttributeVideo &v = c_documentAttributeVideo();
		v.vflags().write(to);
		v.vduration().write(to);
		v.vw().write(to);
		v.vh().write(to);
		if (const auto vpreload_prefix_size = v.vpreload_prefix_size()) vpreload_prefix_size->write(to);
		if (const auto vvideo_start_ts = v.vvideo_start_ts()) vvideo_start_ts->write(to);
		if (const auto vvideo_codec = v.vvideo_codec()) vvideo_codec->write(to);
	} break;
	case mtpc_documentAttributeAudio: {
		const MTPDdocumentAttributeAudio &v = c_documentAttributeAudio();
		v.vflags().write(to);
		v.vduration().write(to);
		if (const auto vtitle = v.vtitle()) vtitle->write(to);
		if (const auto vperformer = v.vperformer()) vperformer->write(to);
		if (const auto vwaveform = v.vwaveform()) vwaveform->write(to);
	} break;
	case mtpc_documentAttributeFilename: {
		const MTPDdocumentAttributeFilename &v = c_documentAttributeFilename();
		v.vfile_name().write(to);
	} break;
	case mtpc_documentAttributeCustomEmoji: {
		const MTPDdocumentAttributeCustomEmoji &v = c_documentAttributeCustomEmoji();
		v.vflags().write(to);
		v.valt().write(to);
		v.vstickerset().write(to);
	} break;
	}
}
