template <typename Accumulator>
void MTPkeyboardButton::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_keyboardButton: {
		const MTPDkeyboardButton &v = c_keyboardButton();
		v.vtext().write(to);
	} break;
	case mtpc_keyboardButtonUrl: {
		const MTPDkeyboardButtonUrl &v = c_keyboardButtonUrl();
		v.vtext().write(to);
		v.vurl().write(to);
	} break;
	case mtpc_keyboardButtonCallback: {
		const MTPDkeyboardButtonCallback &v = c_keyboardButtonCallback();
		v.vflags().write(to);
		v.vtext().write(to);
		v.vdata().write(to);
	} break;
	case mtpc_keyboardButtonRequestPhone: {
		const MTPDkeyboardButtonRequestPhone &v = c_keyboardButtonRequestPhone();
		v.vtext().write(to);
	} break;
	case mtpc_keyboardButtonRequestGeoLocation: {
		const MTPDkeyboardButtonRequestGeoLocation &v = c_keyboardButtonRequestGeoLocation();
		v.vtext().write(to);
	} break;
	case mtpc_keyboardButtonSwitchInline: {
		const MTPDkeyboardButtonSwitchInline &v = c_keyboardButtonSwitchInline();
		v.vflags().write(to);
		v.vtext().write(to);
		v.vquery().write(to);
		if (const auto vpeer_types = v.vpeer_types()) vpeer_types->write(to);
	} break;
	case mtpc_keyboardButtonGame: {
		const MTPDkeyboardButtonGame &v = c_keyboardButtonGame();
		v.vtext().write(to);
	} break;
	case mtpc_keyboardButtonBuy: {
		const MTPDkeyboardButtonBuy &v = c_keyboardButtonBuy();
		v.vtext().write(to);
	} break;
	case mtpc_keyboardButtonUrlAuth: {
		const MTPDkeyboardButtonUrlAuth &v = c_keyboardButtonUrlAuth();
		v.vflags().write(to);
		v.vtext().write(to);
		if (const auto vfwd_text = v.vfwd_text()) vfwd_text->write(to);
		v.vurl().write(to);
		v.vbutton_id().write(to);
	} break;
	case mtpc_inputKeyboardButtonUrlAuth: {
		const MTPDinputKeyboardButtonUrlAuth &v = c_inputKeyboardButtonUrlAuth();
		v.vflags().write(to);
		v.vtext().write(to);
		if (const auto vfwd_text = v.vfwd_text()) vfwd_text->write(to);
		v.vurl().write(to);
		v.vbot().write(to);
	} break;
	case mtpc_keyboardButtonRequestPoll: {
		const MTPDkeyboardButtonRequestPoll &v = c_keyboardButtonRequestPoll();
		v.vflags().write(to);
		if (const auto vquiz = v.vquiz()) vquiz->write(to);
		v.vtext().write(to);
	} break;
	case mtpc_inputKeyboardButtonUserProfile: {
		const MTPDinputKeyboardButtonUserProfile &v = c_inputKeyboardButtonUserProfile();
		v.vtext().write(to);
		v.vuser_id().write(to);
	} break;
	case mtpc_keyboardButtonUserProfile: {
		const MTPDkeyboardButtonUserProfile &v = c_keyboardButtonUserProfile();
		v.vtext().write(to);
		v.vuser_id().write(to);
	} break;
	case mtpc_keyboardButtonWebView: {
		const MTPDkeyboardButtonWebView &v = c_keyboardButtonWebView();
		v.vtext().write(to);
		v.vurl().write(to);
	} break;
	case mtpc_keyboardButtonSimpleWebView: {
		const MTPDkeyboardButtonSimpleWebView &v = c_keyboardButtonSimpleWebView();
		v.vtext().write(to);
		v.vurl().write(to);
	} break;
	case mtpc_keyboardButtonRequestPeer: {
		const MTPDkeyboardButtonRequestPeer &v = c_keyboardButtonRequestPeer();
		v.vtext().write(to);
		v.vbutton_id().write(to);
		v.vpeer_type().write(to);
		v.vmax_quantity().write(to);
	} break;
	case mtpc_inputKeyboardButtonRequestPeer: {
		const MTPDinputKeyboardButtonRequestPeer &v = c_inputKeyboardButtonRequestPeer();
		v.vflags().write(to);
		v.vtext().write(to);
		v.vbutton_id().write(to);
		v.vpeer_type().write(to);
		v.vmax_quantity().write(to);
	} break;
	case mtpc_keyboardButtonCopy: {
		const MTPDkeyboardButtonCopy &v = c_keyboardButtonCopy();
		v.vtext().write(to);
		v.vcopy_text().write(to);
	} break;
	}
}
