	case mtpc_keyboardButtonBuy: setData(new MTPDkeyboardButtonBuy()); break;
	case mtpc_keyboardButtonUrlAuth: setData(new MTPDkeyboardButtonUrlAuth()); break;
	case mtpc_inputKeyboardButtonUrlAuth: setData(new MTPDinputKeyboardButtonUrlAuth()); break;
	case mtpc_keyboardButtonRequestPoll: setData(new MTPDkeyboardButtonRequestPoll()); break;
	case mtpc_inputKeyboardButtonUserProfile: setData(new MTPDinputKeyboardButtonUserProfile()); break;
	case mtpc_keyboardButtonUserProfile: setData(new MTPDkeyboardButtonUserProfile()); break;
	case mtpc_keyboardButtonWebView: setData(new MTPDkeyboardButtonWebView()); break;
	case mtpc_keyboardButtonSimpleWebView: setData(new MTPDkeyboardButtonSimpleWebView()); break;
	case mtpc_keyboardButtonRequestPeer: setData(new MTPDkeyboardButtonRequestPeer()); break;
	case mtpc_inputKeyboardButtonRequestPeer: setData(new MTPDinputKeyboardButtonRequestPeer()); break;
	case mtpc_keyboardButtonCopy: setData(new MTPDkeyboardButtonCopy()); break;
	default: Unexpected("Type in MTPkeyboardButton::MTPkeyboardButton.");
