MTPreplyMarkup::MTPreplyMarkup() = default;
mtpTypeId MTPreplyMarkup::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPreplyMarkup::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_replyKeyboardHide: _type = cons; {
		if (const auto data = new MTPDreplyKeyboardHide(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_replyKeyboardForceReply: _type = cons; {
		if (const auto data = new MTPDreplyKeyboardForceReply(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_replyKeyboardMarkup: _type = cons; {
		if (const auto data = new MTPDreplyKeyboardMarkup(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_replyInlineMarkup: _type = cons; {
		if (const auto data = new MTPDreplyInlineMarkup(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPreplyMarkup::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_replyKeyboardHide: {
		const MTPDreplyKeyboardHide &v = c_replyKeyboardHide();
		v.vflags().write(to);
	} break;
	case mtpc_replyKeyboardForceReply: {
		const MTPDreplyKeyboardForceReply &v = c_replyKeyboardForceReply();
		v.vflags().write(to);
		if (const auto vplaceholder = v.vplaceholder()) vplaceholder->write(to);
	} break;
	case mtpc_replyKeyboardMarkup: {
		const MTPDreplyKeyboardMarkup &v = c_replyKeyboardMarkup();
		v.vflags().write(to);
		v.vrows().write(to);
		if (const auto vplaceholder = v.vplaceholder()) vplaceholder->write(to);
	} break;
	case mtpc_replyInlineMarkup: {
		const MTPDreplyInlineMarkup &v = c_replyInlineMarkup();
		v.vrows().write(to);
	} break;
	}
}
template void MTPreplyMarkup::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPreplyMarkup::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPreplyMarkup::MTPreplyMarkup(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_replyKeyboardHide: setData(new MTPDreplyKeyboardHide()); break;
	case mtpc_replyKeyboardForceReply: setData(new MTPDreplyKeyboardForceReply()); break;
	case mtpc_replyKeyboardMarkup: setData(new MTPDreplyKeyboardMarkup()); break;
	case mtpc_replyInlineMarkup: setData(new MTPDreplyInlineMarkup()); break;
	default: Unexpected("Type in MTPreplyMarkup::MTPreplyMarkup.");
	}
}
