MTPinputChannel::MTPinputChannel() = default;
mtpTypeId MTPinputChannel::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPinputChannel::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_inputChannelEmpty: _type = cons; break;
	case mtpc_inputChannel: _type = cons; {
		if (const auto data = new MTPDinputChannel(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputChannelFromMessage: _type = cons; {
		if (const auto data = new MTPDinputChannelFromMessage(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPinputChannel::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_inputChannel: {
		const MTPDinputChannel &v = c_inputChannel();
		v.vchannel_id().write(to);
		v.vaccess_hash().write(to);
	} break;
	case mtpc_inputChannelFromMessage: {
		const MTPDinputChannelFromMessage &v = c_inputChannelFromMessage();
		v.vpeer().write(to);
		v.vmsg_id().write(to);
		v.vchannel_id().write(to);
	} break;
	}
}
template void MTPinputChannel::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPinputChannel::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPinputChannel::MTPinputChannel(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_inputChannelEmpty: break;
	case mtpc_inputChannel: setData(new MTPDinputChannel()); break;
	case mtpc_inputChannelFromMessage: setData(new MTPDinputChannelFromMessage()); break;
	default: Unexpected("Type in MTPinputChannel::MTPinputChannel.");
	}
}
