MTPbotInlineResult::MTPbotInlineResult() = default;
mtpTypeId MTPbotInlineResult::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPbotInlineResult::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_botInlineResult: _type = cons; {
		if (const auto data = new MTPDbotInlineResult(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_botInlineMediaResult: _type = cons; {
		if (const auto data = new MTPDbotInlineMediaResult(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPbotInlineResult::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_botInlineResult: {
		const MTPDbotInlineResult &v = c_botInlineResult();
		v.vflags().write(to);
		v.vid().write(to);
		v.vtype().write(to);
		if (const auto vtitle = v.vtitle()) vtitle->write(to);
		if (const auto vdescription = v.vdescription()) vdescription->write(to);
		if (const auto vurl = v.vurl()) vurl->write(to);
		if (const auto vthumb = v.vthumb()) vthumb->write(to);
		if (const auto vcontent = v.vcontent()) vcontent->write(to);
		v.vsend_message().write(to);
	} break;
	case mtpc_botInlineMediaResult: {
		const MTPDbotInlineMediaResult &v = c_botInlineMediaResult();
		v.vflags().write(to);
		v.vid().write(to);
		v.vtype().write(to);
		if (const auto vphoto = v.vphoto()) vphoto->write(to);
		if (const auto vdocument = v.vdocument()) vdocument->write(to);
		if (const auto vtitle = v.vtitle()) vtitle->write(to);
		if (const auto vdescription = v.vdescription()) vdescription->write(to);
		v.vsend_message().write(to);
	} break;
	}
}
template void MTPbotInlineResult::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPbotInlineResult::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPbotInlineResult::MTPbotInlineResult(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_botInlineResult: setData(new MTPDbotInlineResult()); break;
	case mtpc_botInlineMediaResult: setData(new MTPDbotInlineMediaResult()); break;
	default: Unexpected("Type in MTPbotInlineResult::MTPbotInlineResult.");
	}
}
