MTPDdraftMessage::MTPDdraftMessage(const MTPflags<MTPDdraftMessage::Flags> &flags_, const MTPInputReplyTo &reply_to_, const MTPstring &message_, const MTPVector<MTPMessageEntity> &entities_, const MTPInputMedia &media_, MTPint date_, MTPlong effect_, const MTPSuggestedPost &suggested_post_) : _flags(flags_), _reply_to(reply_to_), _message(message_), _entities(entities_), _media(media_), _date(date_), _effect(effect_), _suggested_post(suggested_post_) {
}
bool MTPDdraftMessage::read(const mtpPrime *&from, const mtpPrime *end) {
	return _flags.read(from, end)
		&& (vreply_to() ? _reply_to.read(from, end) : ((_reply_to = MTPInputReplyTo()), true))
		&& _message.read(from, end)
		&& (ventities() ? _entities.read(from, end) : ((_entities = MTPVector<MTPMessageEntity>()), true))
		&& (vmedia() ? _media.read(from, end) : ((_media = MTPInputMedia()), true))
		&& _date.read(from, end)
		&& (veffect() ? _effect.read(from, end) : ((_effect = MTPlong()), true))
		&& (vsuggested_post() ? _suggested_post.read(from, end) : ((_suggested_post = MTPSuggestedPost()), true));
}
