template <typename Accumulator>
void MTPpageBlock::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_pageBlockTitle: {
		const MTPDpageBlockTitle &v = c_pageBlockTitle();
		v.vtext().write(to);
	} break;
	case mtpc_pageBlockSubtitle: {
		const MTPDpageBlockSubtitle &v = c_pageBlockSubtitle();
		v.vtext().write(to);
	} break;
	case mtpc_pageBlockAuthorDate: {
		const MTPDpageBlockAuthorDate &v = c_pageBlockAuthorDate();
		v.vauthor().write(to);
		v.vpublished_date().write(to);
	} break;
	case mtpc_pageBlockHeader: {
		const MTPDpageBlockHeader &v = c_pageBlockHeader();
		v.vtext().write(to);
	} break;
	case mtpc_pageBlockSubheader: {
		const MTPDpageBlockSubheader &v = c_pageBlockSubheader();
		v.vtext().write(to);
	} break;
	case mtpc_pageBlockParagraph: {
		const MTPDpageBlockParagraph &v = c_pageBlockParagraph();
		v.vtext().write(to);
	} break;
	case mtpc_pageBlockPreformatted: {
		const MTPDpageBlockPreformatted &v = c_pageBlockPreformatted();
		v.vtext().write(to);
		v.vlanguage().write(to);
	} break;
	case mtpc_pageBlockFooter: {
		const MTPDpageBlockFooter &v = c_pageBlockFooter();
		v.vtext().write(to);
	} break;
	case mtpc_pageBlockAnchor: {
		const MTPDpageBlockAnchor &v = c_pageBlockAnchor();
		v.vname().write(to);
	} break;
	case mtpc_pageBlockList: {
		const MTPDpageBlockList &v = c_pageBlockList();
		v.vitems().write(to);
	} break;
	case mtpc_pageBlockBlockquote: {
		const MTPDpageBlockBlockquote &v = c_pageBlockBlockquote();
		v.vtext().write(to);
		v.vcaption().write(to);
	} break;
	case mtpc_pageBlockPullquote: {
		const MTPDpageBlockPullquote &v = c_pageBlockPullquote();
		v.vtext().write(to);
		v.vcaption().write(to);
	} break;
	case mtpc_pageBlockPhoto: {
		const MTPDpageBlockPhoto &v = c_pageBlockPhoto();
		v.vflags().write(to);
		v.vphoto_id().write(to);
		v.vcaption().write(to);
		if (const auto vurl = v.vurl()) vurl->write(to);
		if (const auto vwebpage_id = v.vwebpage_id()) vwebpage_id->write(to);
	} break;
	case mtpc_pageBlockVideo: {
		const MTPDpageBlockVideo &v = c_pageBlockVideo();
		v.vflags().write(to);
		v.vvideo_id().write(to);
		v.vcaption().write(to);
	} break;
	case mtpc_pageBlockCover: {
		const MTPDpageBlockCover &v = c_pageBlockCover();
		v.vcover().write(to);
	} break;
	case mtpc_pageBlockEmbed: {
		const MTPDpageBlockEmbed &v = c_pageBlockEmbed();
		v.vflags().write(to);
		if (const auto vurl = v.vurl()) vurl->write(to);
		if (const auto vhtml = v.vhtml()) vhtml->write(to);
		if (const auto vposter_photo_id = v.vposter_photo_id()) vposter_photo_id->write(to);
		if (const auto vw = v.vw()) vw->write(to);
		if (const auto vh = v.vh()) vh->write(to);
		v.vcaption().write(to);
	} break;
	case mtpc_pageBlockEmbedPost: {
		const MTPDpageBlockEmbedPost &v = c_pageBlockEmbedPost();
		v.vurl().write(to);
		v.vwebpage_id().write(to);
		v.vauthor_photo_id().write(to);
		v.vauthor().write(to);
		v.vdate().write(to);
		v.vblocks().write(to);
		v.vcaption().write(to);
	} break;
	case mtpc_pageBlockCollage: {
		const MTPDpageBlockCollage &v = c_pageBlockCollage();
		v.vitems().write(to);
		v.vcaption().write(to);
	} break;
	case mtpc_pageBlockSlideshow: {
		const MTPDpageBlockSlideshow &v = c_pageBlockSlideshow();
		v.vitems().write(to);
		v.vcaption().write(to);
	} break;
	case mtpc_pageBlockChannel: {
		const MTPDpageBlockChannel &v = c_pageBlockChannel();
		v.vchannel().write(to);
	} break;
	case mtpc_pageBlockAudio: {
		const MTPDpageBlockAudio &v = c_pageBlockAudio();
		v.vaudio_id().write(to);
		v.vcaption().write(to);
	} break;
	case mtpc_pageBlockKicker: {
		const MTPDpageBlockKicker &v = c_pageBlockKicker();
		v.vtext().write(to);
	} break;
	case mtpc_pageBlockTable: {
		const MTPDpageBlockTable &v = c_pageBlockTable();
		v.vflags().write(to);
		v.vtitle().write(to);
		v.vrows().write(to);
	} break;
	case mtpc_pageBlockOrderedList: {
		const MTPDpageBlockOrderedList &v = c_pageBlockOrderedList();
		v.vitems().write(to);
	} break;
	case mtpc_pageBlockDetails: {
		const MTPDpageBlockDetails &v = c_pageBlockDetails();
		v.vflags().write(to);
		v.vblocks().write(to);
		v.vtitle().write(to);
	} break;
	case mtpc_pageBlockRelatedArticles: {
		const MTPDpageBlockRelatedArticles &v = c_pageBlockRelatedArticles();
		v.vtitle().write(to);
		v.varticles().write(to);
	} break;
	case mtpc_pageBlockMap: {
		const MTPDpageBlockMap &v = c_pageBlockMap();
		v.vgeo().write(to);
		v.vzoom().write(to);
		v.vw().write(to);
		v.vh().write(to);
		v.vcaption().write(to);
	} break;
	}
}
