MTPphoneCallDiscardReason::MTPphoneCallDiscardReason() = default;
mtpTypeId MTPphoneCallDiscardReason::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPphoneCallDiscardReason::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_phoneCallDiscardReasonMissed: _type = cons; break;
	case mtpc_phoneCallDiscardReasonDisconnect: _type = cons; break;
	case mtpc_phoneCallDiscardReasonHangup: _type = cons; break;
	case mtpc_phoneCallDiscardReasonBusy: _type = cons; break;
	case mtpc_phoneCallDiscardReasonMigrateConferenceCall: _type = cons; {
		if (const auto data = new MTPDphoneCallDiscardReasonMigrateConferenceCall(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPphoneCallDiscardReason::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_phoneCallDiscardReasonMigrateConferenceCall: {
		const MTPDphoneCallDiscardReasonMigrateConferenceCall &v = c_phoneCallDiscardReasonMigrateConferenceCall();
		v.vslug().write(to);
	} break;
	}
}
template void MTPphoneCallDiscardReason::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPphoneCallDiscardReason::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPphoneCallDiscardReason::MTPphoneCallDiscardReason(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_phoneCallDiscardReasonMissed: break;
	case mtpc_phoneCallDiscardReasonDisconnect: break;
	case mtpc_phoneCallDiscardReasonHangup: break;
	case mtpc_phoneCallDiscardReasonBusy: break;
	case mtpc_phoneCallDiscardReasonMigrateConferenceCall: setData(new MTPDphoneCallDiscardReasonMigrateConferenceCall()); break;
	default: Unexpected("Type in MTPphoneCallDiscardReason::MTPphoneCallDiscardReason.");
	}
}
const MTPDphoneCallDiscardReasonMissed &MTPphoneCallDiscardReason::c_phoneCallDiscardReasonMissed() const {
	Expects(_type == mtpc_phoneCallDiscardReasonMissed);

	static const MTPDphoneCallDiscardReasonMissed result;
	return result;
}
