template <typename Accumulator>
void MTPinvoice::write(Accumulator &to) const {
	const MTPDinvoice &v = c_invoice();
	v.vflags().write(to);
	v.vcurrency().write(to);
	v.vprices().write(to);
	if (const auto vmax_tip_amount = v.vmax_tip_amount()) vmax_tip_amount->write(to);
	if (const auto vsuggested_tip_amounts = v.vsuggested_tip_amounts()) vsuggested_tip_amounts->write(to);
	if (const auto vterms_url = v.vterms_url()) vterms_url->write(to);
	if (const auto vsubscription_period = v.vsubscription_period()) vsubscription_period->write(to);
}
