MTPphoneCall::MTPphoneCall() = default;
mtpTypeId MTPphoneCall::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPphoneCall::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_phoneCallEmpty: _type = cons; {
		if (const auto data = new MTPDphoneCallEmpty(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_phoneCallWaiting: _type = cons; {
		if (const auto data = new MTPDphoneCallWaiting(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_phoneCallRequested: _type = cons; {
		if (const auto data = new MTPDphoneCallRequested(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_phoneCallAccepted: _type = cons; {
		if (const auto data = new MTPDphoneCallAccepted(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_phoneCall: _type = cons; {
		if (const auto data = new MTPDphoneCall(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_phoneCallDiscarded: _type = cons; {
		if (const auto data = new MTPDphoneCallDiscarded(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPphoneCall::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_phoneCallEmpty: {
		const MTPDphoneCallEmpty &v = c_phoneCallEmpty();
		v.vid().write(to);
	} break;
	case mtpc_phoneCallWaiting: {
		const MTPDphoneCallWaiting &v = c_phoneCallWaiting();
		v.vflags().write(to);
		v.vid().write(to);
		v.vaccess_hash().write(to);
		v.vdate().write(to);
		v.vadmin_id().write(to);
		v.vparticipant_id().write(to);
		v.vprotocol().write(to);
		if (const auto vreceive_date = v.vreceive_date()) vreceive_date->write(to);
	} break;
	case mtpc_phoneCallRequested: {
		const MTPDphoneCallRequested &v = c_phoneCallRequested();
		v.vflags().write(to);
		v.vid().write(to);
		v.vaccess_hash().write(to);
		v.vdate().write(to);
		v.vadmin_id().write(to);
		v.vparticipant_id().write(to);
		v.vg_a_hash().write(to);
		v.vprotocol().write(to);
	} break;
	case mtpc_phoneCallAccepted: {
		const MTPDphoneCallAccepted &v = c_phoneCallAccepted();
		v.vflags().write(to);
		v.vid().write(to);
		v.vaccess_hash().write(to);
		v.vdate().write(to);
		v.vadmin_id().write(to);
		v.vparticipant_id().write(to);
		v.vg_b().write(to);
		v.vprotocol().write(to);
	} break;
	case mtpc_phoneCall: {
		const MTPDphoneCall &v = c_phoneCall();
		v.vflags().write(to);
		v.vid().write(to);
		v.vaccess_hash().write(to);
		v.vdate().write(to);
		v.vadmin_id().write(to);
		v.vparticipant_id().write(to);
		v.vg_a_or_b().write(to);
		v.vkey_fingerprint().write(to);
		v.vprotocol().write(to);
		v.vconnections().write(to);
		v.vstart_date().write(to);
		if (const auto vcustom_parameters = v.vcustom_parameters()) vcustom_parameters->write(to);
	} break;
	case mtpc_phoneCallDiscarded: {
		const MTPDphoneCallDiscarded &v = c_phoneCallDiscarded();
		v.vflags().write(to);
		v.vid().write(to);
		if (const auto vreason = v.vreason()) vreason->write(to);
		if (const auto vduration = v.vduration()) vduration->write(to);
	} break;
	}
}
template void MTPphoneCall::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPphoneCall::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPphoneCall::MTPphoneCall(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_phoneCallEmpty: setData(new MTPDphoneCallEmpty()); break;
	case mtpc_phoneCallWaiting: setData(new MTPDphoneCallWaiting()); break;
	case mtpc_phoneCallRequested: setData(new MTPDphoneCallRequested()); break;
	case mtpc_phoneCallAccepted: setData(new MTPDphoneCallAccepted()); break;
	case mtpc_phoneCall: setData(new MTPDphoneCall()); break;
	case mtpc_phoneCallDiscarded: setData(new MTPDphoneCallDiscarded()); break;
	default: Unexpected("Type in MTPphoneCall::MTPphoneCall.");
	}
}
