bool MTPsecureValueError::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_secureValueErrorData: _type = cons; {
		if (const auto data = new MTPDsecureValueErrorData(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_secureValueErrorFrontSide: _type = cons; {
		if (const auto data = new MTPDsecureValueErrorFrontSide(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_secureValueErrorReverseSide: _type = cons; {
		if (const auto data = new MTPDsecureValueErrorReverseSide(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_secureValueErrorSelfie: _type = cons; {
		if (const auto data = new MTPDsecureValueErrorSelfie(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_secureValueErrorFile: _type = cons; {
		if (const auto data = new MTPDsecureValueErrorFile(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_secureValueErrorFiles: _type = cons; {
		if (const auto data = new MTPDsecureValueErrorFiles(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_secureValueError: _type = cons; {
		if (const auto data = new MTPDsecureValueError(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_secureValueErrorTranslationFile: _type = cons; {
		if (const auto data = new MTPDsecureValueErrorTranslationFile(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_secureValueErrorTranslationFiles: _type = cons; {
		if (const auto data = new MTPDsecureValueErrorTranslationFiles(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
