MTPurlAuthResult::MTPurlAuthResult() = default;
mtpTypeId MTPurlAuthResult::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPurlAuthResult::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_urlAuthResultRequest: _type = cons; {
		if (const auto data = new MTPDurlAuthResultRequest(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_urlAuthResultAccepted: _type = cons; {
		if (const auto data = new MTPDurlAuthResultAccepted(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_urlAuthResultDefault: _type = cons; break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPurlAuthResult::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_urlAuthResultRequest: {
		const MTPDurlAuthResultRequest &v = c_urlAuthResultRequest();
		v.vflags().write(to);
		v.vbot().write(to);
		v.vdomain().write(to);
	} break;
	case mtpc_urlAuthResultAccepted: {
		const MTPDurlAuthResultAccepted &v = c_urlAuthResultAccepted();
		v.vurl().write(to);
	} break;
	}
}
template void MTPurlAuthResult::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPurlAuthResult::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPurlAuthResult::MTPurlAuthResult(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_urlAuthResultRequest: setData(new MTPDurlAuthResultRequest()); break;
	case mtpc_urlAuthResultAccepted: setData(new MTPDurlAuthResultAccepted()); break;
	case mtpc_urlAuthResultDefault: break;
	default: Unexpected("Type in MTPurlAuthResult::MTPurlAuthResult.");
	}
}
