template <typename Accumulator>
void MTPtheme::write(Accumulator &to) const {
	const MTPDtheme &v = c_theme();
	v.vflags().write(to);
	v.vid().write(to);
	v.vaccess_hash().write(to);
	v.vslug().write(to);
	v.vtitle().write(to);
	if (const auto vdocument = v.vdocument()) vdocument->write(to);
	if (const auto vsettings = v.vsettings()) vsettings->write(to);
	if (const auto vemoticon = v.vemoticon()) vemoticon->write(to);
	if (const auto vinstalls_count = v.vinstalls_count()) vinstalls_count->write(to);
}
