mtpTypeId MTPwebPageAttribute::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPwebPageAttribute::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_webPageAttributeTheme: _type = cons; {
		if (const auto data = new MTPDwebPageAttributeTheme(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_webPageAttributeStory: _type = cons; {
		if (const auto data = new MTPDwebPageAttributeStory(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_webPageAttributeStickerSet: _type = cons; {
		if (const auto data = new MTPDwebPageAttributeStickerSet(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_webPageAttributeUniqueStarGift: _type = cons; {
		if (const auto data = new MTPDwebPageAttributeUniqueStarGift(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_webPageAttributeStarGiftCollection: _type = cons; {
		if (const auto data = new MTPDwebPageAttributeStarGiftCollection(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPwebPageAttribute::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_webPageAttributeTheme: {
		const MTPDwebPageAttributeTheme &v = c_webPageAttributeTheme();
		v.vflags().write(to);
		if (const auto vdocuments = v.vdocuments()) vdocuments->write(to);
		if (const auto vsettings = v.vsettings()) vsettings->write(to);
	} break;
	case mtpc_webPageAttributeStory: {
		const MTPDwebPageAttributeStory &v = c_webPageAttributeStory();
		v.vflags().write(to);
		v.vpeer().write(to);
		v.vid().write(to);
		if (const auto vstory = v.vstory()) vstory->write(to);
	} break;
	case mtpc_webPageAttributeStickerSet: {
		const MTPDwebPageAttributeStickerSet &v = c_webPageAttributeStickerSet();
		v.vflags().write(to);
		v.vstickers().write(to);
	} break;
	case mtpc_webPageAttributeUniqueStarGift: {
		const MTPDwebPageAttributeUniqueStarGift &v = c_webPageAttributeUniqueStarGift();
		v.vgift().write(to);
	} break;
	case mtpc_webPageAttributeStarGiftCollection: {
		const MTPDwebPageAttributeStarGiftCollection &v = c_webPageAttributeStarGiftCollection();
		v.vicons().write(to);
	} break;
	}
}
template void MTPwebPageAttribute::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPwebPageAttribute::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
