MTPdialogFilter::MTPdialogFilter() = default;
mtpTypeId MTPdialogFilter::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPdialogFilter::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_dialogFilter: _type = cons; {
		if (const auto data = new MTPDdialogFilter(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_dialogFilterDefault: _type = cons; break;
	case mtpc_dialogFilterChatlist: _type = cons; {
		if (const auto data = new MTPDdialogFilterChatlist(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPdialogFilter::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_dialogFilter: {
		const MTPDdialogFilter &v = c_dialogFilter();
		v.vflags().write(to);
		v.vid().write(to);
		v.vtitle().write(to);
		if (const auto vemoticon = v.vemoticon()) vemoticon->write(to);
		if (const auto vcolor = v.vcolor()) vcolor->write(to);
		v.vpinned_peers().write(to);
		v.vinclude_peers().write(to);
		v.vexclude_peers().write(to);
	} break;
	case mtpc_dialogFilterChatlist: {
		const MTPDdialogFilterChatlist &v = c_dialogFilterChatlist();
		v.vflags().write(to);
		v.vid().write(to);
		v.vtitle().write(to);
		if (const auto vemoticon = v.vemoticon()) vemoticon->write(to);
		if (const auto vcolor = v.vcolor()) vcolor->write(to);
		v.vpinned_peers().write(to);
		v.vinclude_peers().write(to);
	} break;
	}
}
template void MTPdialogFilter::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPdialogFilter::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPdialogFilter::MTPdialogFilter(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_dialogFilter: setData(new MTPDdialogFilter()); break;
	case mtpc_dialogFilterDefault: break;
	case mtpc_dialogFilterChatlist: setData(new MTPDdialogFilterChatlist()); break;
	default: Unexpected("Type in MTPdialogFilter::MTPdialogFilter.");
	}
}
