mtpTypeId MTPinputInvoice::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPinputInvoice::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_inputInvoiceMessage: _type = cons; {
		if (const auto data = new MTPDinputInvoiceMessage(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceSlug: _type = cons; {
		if (const auto data = new MTPDinputInvoiceSlug(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoicePremiumGiftCode: _type = cons; {
		if (const auto data = new MTPDinputInvoicePremiumGiftCode(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceStars: _type = cons; {
		if (const auto data = new MTPDinputInvoiceStars(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceChatInviteSubscription: _type = cons; {
		if (const auto data = new MTPDinputInvoiceChatInviteSubscription(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceStarGift: _type = cons; {
		if (const auto data = new MTPDinputInvoiceStarGift(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceStarGiftUpgrade: _type = cons; {
		if (const auto data = new MTPDinputInvoiceStarGiftUpgrade(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceStarGiftTransfer: _type = cons; {
		if (const auto data = new MTPDinputInvoiceStarGiftTransfer(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoicePremiumGiftStars: _type = cons; {
		if (const auto data = new MTPDinputInvoicePremiumGiftStars(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceBusinessBotTransferStars: _type = cons; {
		if (const auto data = new MTPDinputInvoiceBusinessBotTransferStars(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceStarGiftResale: _type = cons; {
		if (const auto data = new MTPDinputInvoiceStarGiftResale(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputInvoiceStarGiftPrepaidUpgrade: _type = cons; {
		if (const auto data = new MTPDinputInvoiceStarGiftPrepaidUpgrade(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPinputInvoice::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_inputInvoiceMessage: {
		const MTPDinputInvoiceMessage &v = c_inputInvoiceMessage();
		v.vpeer().write(to);
		v.vmsg_id().write(to);
	} break;
	case mtpc_inputInvoiceSlug: {
		const MTPDinputInvoiceSlug &v = c_inputInvoiceSlug();
		v.vslug().write(to);
	} break;
	case mtpc_inputInvoicePremiumGiftCode: {
		const MTPDinputInvoicePremiumGiftCode &v = c_inputInvoicePremiumGiftCode();
		v.vpurpose().write(to);
		v.voption().write(to);
	} break;
	case mtpc_inputInvoiceStars: {
		const MTPDinputInvoiceStars &v = c_inputInvoiceStars();
		v.vpurpose().write(to);
	} break;
	case mtpc_inputInvoiceChatInviteSubscription: {
		const MTPDinputInvoiceChatInviteSubscription &v = c_inputInvoiceChatInviteSubscription();
		v.vhash().write(to);
	} break;
	case mtpc_inputInvoiceStarGift: {
		const MTPDinputInvoiceStarGift &v = c_inputInvoiceStarGift();
		v.vflags().write(to);
		v.vpeer().write(to);
		v.vgift_id().write(to);
		if (const auto vmessage = v.vmessage()) vmessage->write(to);
	} break;
	case mtpc_inputInvoiceStarGiftUpgrade: {
		const MTPDinputInvoiceStarGiftUpgrade &v = c_inputInvoiceStarGiftUpgrade();
		v.vflags().write(to);
		v.vstargift().write(to);
	} break;
	case mtpc_inputInvoiceStarGiftTransfer: {
		const MTPDinputInvoiceStarGiftTransfer &v = c_inputInvoiceStarGiftTransfer();
		v.vstargift().write(to);
		v.vto_id().write(to);
	} break;
	case mtpc_inputInvoicePremiumGiftStars: {
		const MTPDinputInvoicePremiumGiftStars &v = c_inputInvoicePremiumGiftStars();
		v.vflags().write(to);
		v.vuser_id().write(to);
		v.vmonths().write(to);
		if (const auto vmessage = v.vmessage()) vmessage->write(to);
	} break;
	case mtpc_inputInvoiceBusinessBotTransferStars: {
		const MTPDinputInvoiceBusinessBotTransferStars &v = c_inputInvoiceBusinessBotTransferStars();
		v.vbot().write(to);
		v.vstars().write(to);
	} break;
	case mtpc_inputInvoiceStarGiftResale: {
		const MTPDinputInvoiceStarGiftResale &v = c_inputInvoiceStarGiftResale();
		v.vflags().write(to);
		v.vslug().write(to);
		v.vto_id().write(to);
	} break;
	case mtpc_inputInvoiceStarGiftPrepaidUpgrade: {
		const MTPDinputInvoiceStarGiftPrepaidUpgrade &v = c_inputInvoiceStarGiftPrepaidUpgrade();
		v.vpeer().write(to);
		v.vhash().write(to);
	} break;
	}
}
