MTPinputStorePaymentPurpose::MTPinputStorePaymentPurpose() = default;
mtpTypeId MTPinputStorePaymentPurpose::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPinputStorePaymentPurpose::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_inputStorePaymentPremiumSubscription: _type = cons; {
		if (const auto data = new MTPDinputStorePaymentPremiumSubscription(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputStorePaymentGiftPremium: _type = cons; {
		if (const auto data = new MTPDinputStorePaymentGiftPremium(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputStorePaymentPremiumGiftCode: _type = cons; {
		if (const auto data = new MTPDinputStorePaymentPremiumGiftCode(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputStorePaymentPremiumGiveaway: _type = cons; {
		if (const auto data = new MTPDinputStorePaymentPremiumGiveaway(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputStorePaymentStarsTopup: _type = cons; {
		if (const auto data = new MTPDinputStorePaymentStarsTopup(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputStorePaymentStarsGift: _type = cons; {
		if (const auto data = new MTPDinputStorePaymentStarsGift(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputStorePaymentStarsGiveaway: _type = cons; {
		if (const auto data = new MTPDinputStorePaymentStarsGiveaway(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputStorePaymentAuthCode: _type = cons; {
		if (const auto data = new MTPDinputStorePaymentAuthCode(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPinputStorePaymentPurpose::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_inputStorePaymentPremiumSubscription: {
		const MTPDinputStorePaymentPremiumSubscription &v = c_inputStorePaymentPremiumSubscription();
		v.vflags().write(to);
	} break;
	case mtpc_inputStorePaymentGiftPremium: {
		const MTPDinputStorePaymentGiftPremium &v = c_inputStorePaymentGiftPremium();
		v.vuser_id().write(to);
		v.vcurrency().write(to);
		v.vamount().write(to);
	} break;
	case mtpc_inputStorePaymentPremiumGiftCode: {
		const MTPDinputStorePaymentPremiumGiftCode &v = c_inputStorePaymentPremiumGiftCode();
		v.vflags().write(to);
		v.vusers().write(to);
		if (const auto vboost_peer = v.vboost_peer()) vboost_peer->write(to);
		v.vcurrency().write(to);
		v.vamount().write(to);
		if (const auto vmessage = v.vmessage()) vmessage->write(to);
	} break;
	case mtpc_inputStorePaymentPremiumGiveaway: {
		const MTPDinputStorePaymentPremiumGiveaway &v = c_inputStorePaymentPremiumGiveaway();
		v.vflags().write(to);
		v.vboost_peer().write(to);
		if (const auto vadditional_peers = v.vadditional_peers()) vadditional_peers->write(to);
		if (const auto vcountries_iso2 = v.vcountries_iso2()) vcountries_iso2->write(to);
		if (const auto vprize_description = v.vprize_description()) vprize_description->write(to);
		v.vrandom_id().write(to);
		v.vuntil_date().write(to);
		v.vcurrency().write(to);
		v.vamount().write(to);
	} break;
	case mtpc_inputStorePaymentStarsTopup: {
		const MTPDinputStorePaymentStarsTopup &v = c_inputStorePaymentStarsTopup();
		v.vflags().write(to);
		v.vstars().write(to);
		v.vcurrency().write(to);
		v.vamount().write(to);
		if (const auto vspend_purpose_peer = v.vspend_purpose_peer()) vspend_purpose_peer->write(to);
	} break;
	case mtpc_inputStorePaymentStarsGift: {
		const MTPDinputStorePaymentStarsGift &v = c_inputStorePaymentStarsGift();
		v.vuser_id().write(to);
		v.vstars().write(to);
		v.vcurrency().write(to);
		v.vamount().write(to);
	} break;
	case mtpc_inputStorePaymentStarsGiveaway: {
		const MTPDinputStorePaymentStarsGiveaway &v = c_inputStorePaymentStarsGiveaway();
		v.vflags().write(to);
		v.vstars().write(to);
		v.vboost_peer().write(to);
		if (const auto vadditional_peers = v.vadditional_peers()) vadditional_peers->write(to);
		if (const auto vcountries_iso2 = v.vcountries_iso2()) vcountries_iso2->write(to);
		if (const auto vprize_description = v.vprize_description()) vprize_description->write(to);
		v.vrandom_id().write(to);
		v.vuntil_date().write(to);
		v.vcurrency().write(to);
		v.vamount().write(to);
		v.vusers().write(to);
	} break;
	case mtpc_inputStorePaymentAuthCode: {
		const MTPDinputStorePaymentAuthCode &v = c_inputStorePaymentAuthCode();
		v.vflags().write(to);
		v.vphone_number().write(to);
		v.vphone_code_hash().write(to);
		v.vcurrency().write(to);
		v.vamount().write(to);
	} break;
	}
}
