MTPemojiStatus::MTPemojiStatus() = default;
mtpTypeId MTPemojiStatus::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPemojiStatus::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_emojiStatusEmpty: _type = cons; break;
	case mtpc_emojiStatus: _type = cons; {
		if (const auto data = new MTPDemojiStatus(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_emojiStatusCollectible: _type = cons; {
		if (const auto data = new MTPDemojiStatusCollectible(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputEmojiStatusCollectible: _type = cons; {
		if (const auto data = new MTPDinputEmojiStatusCollectible(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPemojiStatus::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_emojiStatus: {
		const MTPDemojiStatus &v = c_emojiStatus();
		v.vflags().write(to);
		v.vdocument_id().write(to);
		if (const auto vuntil = v.vuntil()) vuntil->write(to);
	} break;
	case mtpc_emojiStatusCollectible: {
		const MTPDemojiStatusCollectible &v = c_emojiStatusCollectible();
		v.vflags().write(to);
		v.vcollectible_id().write(to);
		v.vdocument_id().write(to);
		v.vtitle().write(to);
		v.vslug().write(to);
		v.vpattern_document_id().write(to);
		v.vcenter_color().write(to);
		v.vedge_color().write(to);
		v.vpattern_color().write(to);
		v.vtext_color().write(to);
		if (const auto vuntil = v.vuntil()) vuntil->write(to);
	} break;
	case mtpc_inputEmojiStatusCollectible: {
		const MTPDinputEmojiStatusCollectible &v = c_inputEmojiStatusCollectible();
		v.vflags().write(to);
		v.vcollectible_id().write(to);
		if (const auto vuntil = v.vuntil()) vuntil->write(to);
	} break;
	}
}
template void MTPemojiStatus::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPemojiStatus::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPemojiStatus::MTPemojiStatus(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_emojiStatusEmpty: break;
	case mtpc_emojiStatus: setData(new MTPDemojiStatus()); break;
	case mtpc_emojiStatusCollectible: setData(new MTPDemojiStatusCollectible()); break;
	case mtpc_inputEmojiStatusCollectible: setData(new MTPDinputEmojiStatusCollectible()); break;
	default: Unexpected("Type in MTPemojiStatus::MTPemojiStatus.");
	}
}
