MTPrequestPeerType::MTPrequestPeerType() = default;
mtpTypeId MTPrequestPeerType::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPrequestPeerType::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_requestPeerTypeUser: _type = cons; {
		if (const auto data = new MTPDrequestPeerTypeUser(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_requestPeerTypeChat: _type = cons; {
		if (const auto data = new MTPDrequestPeerTypeChat(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_requestPeerTypeBroadcast: _type = cons; {
		if (const auto data = new MTPDrequestPeerTypeBroadcast(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPrequestPeerType::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_requestPeerTypeUser: {
		const MTPDrequestPeerTypeUser &v = c_requestPeerTypeUser();
		v.vflags().write(to);
		if (const auto vbot = v.vbot()) vbot->write(to);
		if (const auto vpremium = v.vpremium()) vpremium->write(to);
	} break;
	case mtpc_requestPeerTypeChat: {
		const MTPDrequestPeerTypeChat &v = c_requestPeerTypeChat();
		v.vflags().write(to);
		if (const auto vhas_username = v.vhas_username()) vhas_username->write(to);
		if (const auto vforum = v.vforum()) vforum->write(to);
		if (const auto vuser_admin_rights = v.vuser_admin_rights()) vuser_admin_rights->write(to);
		if (const auto vbot_admin_rights = v.vbot_admin_rights()) vbot_admin_rights->write(to);
	} break;
	case mtpc_requestPeerTypeBroadcast: {
		const MTPDrequestPeerTypeBroadcast &v = c_requestPeerTypeBroadcast();
		v.vflags().write(to);
		if (const auto vhas_username = v.vhas_username()) vhas_username->write(to);
		if (const auto vuser_admin_rights = v.vuser_admin_rights()) vuser_admin_rights->write(to);
		if (const auto vbot_admin_rights = v.vbot_admin_rights()) vbot_admin_rights->write(to);
	} break;
	}
}
template void MTPrequestPeerType::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPrequestPeerType::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPrequestPeerType::MTPrequestPeerType(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_requestPeerTypeUser: setData(new MTPDrequestPeerTypeUser()); break;
	case mtpc_requestPeerTypeChat: setData(new MTPDrequestPeerTypeChat()); break;
	case mtpc_requestPeerTypeBroadcast: setData(new MTPDrequestPeerTypeBroadcast()); break;
	default: Unexpected("Type in MTPrequestPeerType::MTPrequestPeerType.");
	}
}
