MTPinputReplyTo::MTPinputReplyTo() = default;
mtpTypeId MTPinputReplyTo::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPinputReplyTo::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_inputReplyToMessage: _type = cons; {
		if (const auto data = new MTPDinputReplyToMessage(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputReplyToStory: _type = cons; {
		if (const auto data = new MTPDinputReplyToStory(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputReplyToMonoForum: _type = cons; {
		if (const auto data = new MTPDinputReplyToMonoForum(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPinputReplyTo::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_inputReplyToMessage: {
		const MTPDinputReplyToMessage &v = c_inputReplyToMessage();
		v.vflags().write(to);
		v.vreply_to_msg_id().write(to);
		if (const auto vtop_msg_id = v.vtop_msg_id()) vtop_msg_id->write(to);
		if (const auto vreply_to_peer_id = v.vreply_to_peer_id()) vreply_to_peer_id->write(to);
		if (const auto vquote_text = v.vquote_text()) vquote_text->write(to);
		if (const auto vquote_entities = v.vquote_entities()) vquote_entities->write(to);
		if (const auto vquote_offset = v.vquote_offset()) vquote_offset->write(to);
		if (const auto vmonoforum_peer_id = v.vmonoforum_peer_id()) vmonoforum_peer_id->write(to);
		if (const auto vtodo_item_id = v.vtodo_item_id()) vtodo_item_id->write(to);
	} break;
	case mtpc_inputReplyToStory: {
		const MTPDinputReplyToStory &v = c_inputReplyToStory();
		v.vpeer().write(to);
		v.vstory_id().write(to);
	} break;
	case mtpc_inputReplyToMonoForum: {
		const MTPDinputReplyToMonoForum &v = c_inputReplyToMonoForum();
		v.vmonoforum_peer_id().write(to);
	} break;
	}
}
template void MTPinputReplyTo::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPinputReplyTo::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPinputReplyTo::MTPinputReplyTo(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_inputReplyToMessage: setData(new MTPDinputReplyToMessage()); break;
	case mtpc_inputReplyToStory: setData(new MTPDinputReplyToStory()); break;
	case mtpc_inputReplyToMonoForum: setData(new MTPDinputReplyToMonoForum()); break;
	default: Unexpected("Type in MTPinputReplyTo::MTPinputReplyTo.");
	}
}
