template <typename Accumulator>
void MTPmediaAreaCoordinates::write(Accumulator &to) const {
	const MTPDmediaAreaCoordinates &v = c_mediaAreaCoordinates();
	v.vflags().write(to);
	v.vx().write(to);
	v.vy().write(to);
	v.vw().write(to);
	v.vh().write(to);
	v.vrotation().write(to);
	if (const auto vradius = v.vradius()) vradius->write(to);
}
