mtpTypeId MTPpayments_giveawayInfo::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPpayments_giveawayInfo::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_payments_giveawayInfo: _type = cons; {
		if (const auto data = new MTPDpayments_giveawayInfo(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_payments_giveawayInfoResults: _type = cons; {
		if (const auto data = new MTPDpayments_giveawayInfoResults(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPpayments_giveawayInfo::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_payments_giveawayInfo: {
		const MTPDpayments_giveawayInfo &v = c_payments_giveawayInfo();
		v.vflags().write(to);
		v.vstart_date().write(to);
		if (const auto vjoined_too_early_date = v.vjoined_too_early_date()) vjoined_too_early_date->write(to);
		if (const auto vadmin_disallowed_chat_id = v.vadmin_disallowed_chat_id()) vadmin_disallowed_chat_id->write(to);
		if (const auto vdisallowed_country = v.vdisallowed_country()) vdisallowed_country->write(to);
	} break;
	case mtpc_payments_giveawayInfoResults: {
		const MTPDpayments_giveawayInfoResults &v = c_payments_giveawayInfoResults();
		v.vflags().write(to);
		v.vstart_date().write(to);
		if (const auto vgift_code_slug = v.vgift_code_slug()) vgift_code_slug->write(to);
		if (const auto vstars_prize = v.vstars_prize()) vstars_prize->write(to);
		v.vfinish_date().write(to);
		v.vwinners_count().write(to);
		if (const auto vactivated_count = v.vactivated_count()) vactivated_count->write(to);
	} break;
	}
}
