MTPbusinessAwayMessageSchedule::MTPbusinessAwayMessageSchedule() = default;
mtpTypeId MTPbusinessAwayMessageSchedule::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPbusinessAwayMessageSchedule::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_businessAwayMessageScheduleAlways: _type = cons; break;
	case mtpc_businessAwayMessageScheduleOutsideWorkHours: _type = cons; break;
	case mtpc_businessAwayMessageScheduleCustom: _type = cons; {
		if (const auto data = new MTPDbusinessAwayMessageScheduleCustom(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPbusinessAwayMessageSchedule::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_businessAwayMessageScheduleCustom: {
		const MTPDbusinessAwayMessageScheduleCustom &v = c_businessAwayMessageScheduleCustom();
		v.vstart_date().write(to);
		v.vend_date().write(to);
	} break;
	}
}
template void MTPbusinessAwayMessageSchedule::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPbusinessAwayMessageSchedule::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPbusinessAwayMessageSchedule::MTPbusinessAwayMessageSchedule(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_businessAwayMessageScheduleAlways: break;
	case mtpc_businessAwayMessageScheduleOutsideWorkHours: break;
	case mtpc_businessAwayMessageScheduleCustom: setData(new MTPDbusinessAwayMessageScheduleCustom()); break;
	default: Unexpected("Type in MTPbusinessAwayMessageSchedule::MTPbusinessAwayMessageSchedule.");
	}
}
const MTPDbusinessAwayMessageScheduleAlways &MTPbusinessAwayMessageSchedule::c_businessAwayMessageScheduleAlways() const {
	Expects(_type == mtpc_businessAwayMessageScheduleAlways);

	static const MTPDbusinessAwayMessageScheduleAlways result;
	return result;
}
