MTPinputCollectible::MTPinputCollectible() = default;
mtpTypeId MTPinputCollectible::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPinputCollectible::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_inputCollectibleUsername: _type = cons; {
		if (const auto data = new MTPDinputCollectibleUsername(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_inputCollectiblePhone: _type = cons; {
		if (const auto data = new MTPDinputCollectiblePhone(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPinputCollectible::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_inputCollectibleUsername: {
		const MTPDinputCollectibleUsername &v = c_inputCollectibleUsername();
		v.vusername().write(to);
	} break;
	case mtpc_inputCollectiblePhone: {
		const MTPDinputCollectiblePhone &v = c_inputCollectiblePhone();
		v.vphone().write(to);
	} break;
	}
}
template void MTPinputCollectible::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPinputCollectible::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPinputCollectible::MTPinputCollectible(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_inputCollectibleUsername: setData(new MTPDinputCollectibleUsername()); break;
	case mtpc_inputCollectiblePhone: setData(new MTPDinputCollectiblePhone()); break;
	default: Unexpected("Type in MTPinputCollectible::MTPinputCollectible.");
	}
}
