bool MTPstarGift::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_starGift: _type = cons; {
		if (const auto data = new MTPDstarGift(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_starGiftUnique: _type = cons; {
		if (const auto data = new MTPDstarGiftUnique(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPstarGift::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_starGift: {
		const MTPDstarGift &v = c_starGift();
		v.vflags().write(to);
		v.vid().write(to);
		v.vsticker().write(to);
		v.vstars().write(to);
		if (const auto vavailability_remains = v.vavailability_remains()) vavailability_remains->write(to);
		if (const auto vavailability_total = v.vavailability_total()) vavailability_total->write(to);
		if (const auto vavailability_resale = v.vavailability_resale()) vavailability_resale->write(to);
		v.vconvert_stars().write(to);
		if (const auto vfirst_sale_date = v.vfirst_sale_date()) vfirst_sale_date->write(to);
		if (const auto vlast_sale_date = v.vlast_sale_date()) vlast_sale_date->write(to);
		if (const auto vupgrade_stars = v.vupgrade_stars()) vupgrade_stars->write(to);
		if (const auto vresell_min_stars = v.vresell_min_stars()) vresell_min_stars->write(to);
		if (const auto vtitle = v.vtitle()) vtitle->write(to);
		if (const auto vreleased_by = v.vreleased_by()) vreleased_by->write(to);
		if (const auto vper_user_total = v.vper_user_total()) vper_user_total->write(to);
		if (const auto vper_user_remains = v.vper_user_remains()) vper_user_remains->write(to);
		if (const auto vlocked_until_date = v.vlocked_until_date()) vlocked_until_date->write(to);
	} break;
	case mtpc_starGiftUnique: {
		const MTPDstarGiftUnique &v = c_starGiftUnique();
		v.vflags().write(to);
		v.vid().write(to);
		v.vgift_id().write(to);
		v.vtitle().write(to);
		v.vslug().write(to);
		v.vnum().write(to);
		if (const auto vowner_id = v.vowner_id()) vowner_id->write(to);
		if (const auto vowner_name = v.vowner_name()) vowner_name->write(to);
		if (const auto vowner_address = v.vowner_address()) vowner_address->write(to);
		v.vattributes().write(to);
		v.vavailability_issued().write(to);
		v.vavailability_total().write(to);
		if (const auto vgift_address = v.vgift_address()) vgift_address->write(to);
		if (const auto vresell_amount = v.vresell_amount()) vresell_amount->write(to);
		if (const auto vreleased_by = v.vreleased_by()) vreleased_by->write(to);
		if (const auto vvalue_amount = v.vvalue_amount()) vvalue_amount->write(to);
		if (const auto vvalue_currency = v.vvalue_currency()) vvalue_currency->write(to);
		if (const auto vtheme_peer = v.vtheme_peer()) vtheme_peer->write(to);
	} break;
	}
}
