bool MTPstarGiftAttribute::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_starGiftAttributeModel: _type = cons; {
		if (const auto data = new MTPDstarGiftAttributeModel(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_starGiftAttributePattern: _type = cons; {
		if (const auto data = new MTPDstarGiftAttributePattern(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_starGiftAttributeBackdrop: _type = cons; {
		if (const auto data = new MTPDstarGiftAttributeBackdrop(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_starGiftAttributeOriginalDetails: _type = cons; {
		if (const auto data = new MTPDstarGiftAttributeOriginalDetails(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPstarGiftAttribute::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_starGiftAttributeModel: {
		const MTPDstarGiftAttributeModel &v = c_starGiftAttributeModel();
		v.vname().write(to);
		v.vdocument().write(to);
		v.vrarity_permille().write(to);
	} break;
	case mtpc_starGiftAttributePattern: {
		const MTPDstarGiftAttributePattern &v = c_starGiftAttributePattern();
		v.vname().write(to);
		v.vdocument().write(to);
		v.vrarity_permille().write(to);
	} break;
	case mtpc_starGiftAttributeBackdrop: {
		const MTPDstarGiftAttributeBackdrop &v = c_starGiftAttributeBackdrop();
		v.vname().write(to);
		v.vbackdrop_id().write(to);
		v.vcenter_color().write(to);
		v.vedge_color().write(to);
		v.vpattern_color().write(to);
		v.vtext_color().write(to);
		v.vrarity_permille().write(to);
	} break;
	case mtpc_starGiftAttributeOriginalDetails: {
		const MTPDstarGiftAttributeOriginalDetails &v = c_starGiftAttributeOriginalDetails();
		v.vflags().write(to);
		if (const auto vsender_id = v.vsender_id()) vsender_id->write(to);
		v.vrecipient_id().write(to);
		v.vdate().write(to);
		if (const auto vmessage = v.vmessage()) vmessage->write(to);
	} break;
	}
}
