MTPserver_DH_Params::MTPserver_DH_Params() = default;
mtpTypeId MTPserver_DH_Params::type() const {
	Expects(_type != 0);

	return _type;
}
bool MTPserver_DH_Params::read(const mtpPrime *&from, const mtpPrime *end, mtpTypeId cons) {
	switch (cons) {
	case mtpc_server_DH_params_fail: _type = cons; {
		if (const auto data = new MTPDserver_DH_params_fail(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	case mtpc_server_DH_params_ok: _type = cons; {
		if (const auto data = new MTPDserver_DH_params_ok(); data->read(from, end)) {
			setData(data);
		} else {
			delete data;
			return false;
		}
	} break;
	default: return false;
	}
	return true;
}
template <typename Accumulator>
void MTPserver_DH_Params::write(Accumulator &to) const {
	switch (_type) {
	case mtpc_server_DH_params_fail: {
		const MTPDserver_DH_params_fail &v = c_server_DH_params_fail();
		v.vnonce().write(to);
		v.vserver_nonce().write(to);
		v.vnew_nonce_hash().write(to);
	} break;
	case mtpc_server_DH_params_ok: {
		const MTPDserver_DH_params_ok &v = c_server_DH_params_ok();
		v.vnonce().write(to);
		v.vserver_nonce().write(to);
		v.vencrypted_answer().write(to);
	} break;
	}
}
template void MTPserver_DH_Params::write<mtpBuffer>(mtpBuffer &to) const;
template void MTPserver_DH_Params::write<::tl::details::LengthCounter>(::tl::details::LengthCounter &to) const;
MTPserver_DH_Params::MTPserver_DH_Params(mtpTypeId type) : _type(type) {
	switch (type) {
	case mtpc_server_DH_params_fail: setData(new MTPDserver_DH_params_fail()); break;
	case mtpc_server_DH_params_ok: setData(new MTPDserver_DH_params_ok()); break;
	default: Unexpected("Type in MTPserver_DH_Params::MTPserver_DH_Params.");
	}
}
